-- Mauritania fourth preparatory year (mapped grade 10): 43 original
-- supplementary exercises across existing official-import title stubs.
-- Independent educational prose; all ministry/source matching is pending.
DO $dadyoom$
DECLARE r RECORD; target_id uuid; prior text; nact integer; hasprogress integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"47c690ea-57d6-4d08-8da6-e6cb39e7e354","n":1,"title":"رسم التنوين","passage":"التنوين نون ساكنة تلحق آخر الاسم في النطق لا في الكتابة، وتدل عليه علامتان في ضبط الحركة. في «كتابٌ» تنوين ضم، وفي «كتابًا» تنوين فتح مع الألف في موضعه المعتاد، مع وجود حالات إملائية خاصة. يساعد ضبط النطق على تجنب كتابة النون حرفًا في آخر الاسم.","question":"ما العلامة المضبوطة في «كتابٌ»؟","correct":"تنوين الضم","wrong":["تنوين الكسر","همزة وصل","تنوين الفتح"],"practice":"اضبط ستة أسماء بتنوين الرفع والنصب والجر، وفسر كتابة الألف حيث تلزم.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"47c690ea-57d6-4d08-8da6-e6cb39e7e354","n":2,"title":"رسم التاء في آخر الكلمة","passage":"تأتي التاء مربوطة كما في «مدرسة»، أو مفتوحة كما في «بيت»، بينما في «وجه» هاء أصلية. نميز الحرف بنطق الكلمة مع الوصل والوقف وفهم بنيتها، فلا يجوز تحويل كل هاء أخيرة إلى تاء مربوطة.","question":"ما الحرف الأخير في «مدرسة»؟","correct":"تاء مربوطة","wrong":["تاء مفتوحة","هاء أصلية","واو"],"practice":"اكتب ثماني كلمات وصنف نهاياتها، ثم اشرح أربع حالات ملتبسة.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"47c690ea-57d6-4d08-8da6-e6cb39e7e354","n":3,"title":"همزة الوصل والقطع","passage":"تثبت همزة القطع لفظًا في البدء والوصل مثل «أحمد»، أما همزة الوصل فتثبت في الابتداء وتسقط في درج الكلام في مواضعها، مثل أول «استمع». تُراجع قاعدة الكلمة لا عدد أحرفها وحده.","question":"ما نوع همزة «استمع»؟","correct":"همزة وصل","wrong":["همزة قطع","همزة متوسطة","همزة متطرفة"],"practice":"اصنع جدولًا بست كلمات تبدأ بهمزة وصل وست بهمزة قطع، مع ضبط السبب.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"548a96ab-831f-4c39-98df-9ea1ac528a94","n":1,"title":"الخبر والإنشاء وأنواع الإنشاء","passage":"الجملة الخبرية تحتمل التصديق أو التكذيب بحسب المضمون مثل «المكتبة مفتوحة»، أما الإنشائية فتنشئ طلبًا أو تعجبًا أو استفهامًا مثل «هل المكتبة مفتوحة؟». يتغير الغرض البلاغي بحسب السياق لا علامة الترقيم وحدها.","question":"أي جملة إنشائية استفهامية؟","correct":"هل المكتبة مفتوحة؟","wrong":["المكتبة مفتوحة","وصل الطلاب","الكتاب جديد"],"practice":"اكتب أربعة أخبار وأربعة أساليب إنشاء متنوعة مع بيان الغرض.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"548a96ab-831f-4c39-98df-9ea1ac528a94","n":2,"title":"التشبيه","passage":"يقارن التشبيه بين شيئين يتشاركان صفة؛ في «العلم كالنور في الهداية» العلم مشبه والنور مشبه به والكاف أداة والهداية وجه الشبه. قد تحذف الأداة أو الوجه في بعض الصور، ويفيد التحليل في فهم أثر التشبيه.","question":"ما المشبه به في «العلم كالنور»؟","correct":"النور","wrong":["العلم","الكاف","الهداية"],"practice":"أنشئ تشبيهين من سياق المدرسة وحدد الأركان والأثر.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"548a96ab-831f-4c39-98df-9ea1ac528a94","n":3,"title":"الحقيقة والمجاز","passage":"في «أضاء المصباح الغرفة» معنى «أضاء» حقيقي، وفي «أضاءت المعرفة طريقه» استُعمل مجازًا لبيان أثر الفهم. يتطلب الحكم على المجاز قرينة تمنع أو تبعد المعنى الحرفي، فلا تصنف كل عبارة مؤثرة على أنها مجاز.","question":"أي استعمال للإضاءة مجازي في المثال؟","correct":"أضاءت المعرفة طريقه","wrong":["أضاء المصباح الغرفة","أشعلت المصابيح","أضاءت الشمس المكان"],"practice":"اكتب مثالين للحقيقة ومثالين للمجاز مع القرينة.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"efd943c3-1ce1-4894-b379-b4fa17b98240","n":1,"title":"حقوق الإنسان","passage":"تتضمن حقوق الإنسان مبادئ مثل الكرامة وعدم التمييز والمساواة في الحماية القانونية، ويحتاج الحديث عن الحقوق المحددة إلى وثائق قانونية موثوقة لا شعارات فقط. في مثال مستقل تعطي مدرسة كل طالب فرصة متساوية للتقدم لنشاط بقاعدة معلنة.","question":"ما التصرف الذي يعبّر عن تكافؤ الفرص في المثال؟","correct":"قواعد قبول واحدة معلنة للجميع","wrong":["اختيار حسب إشاعة","حجب المعايير","استبعاد دون سبب"],"practice":"اكتب فقرة عن حق إنساني من وثيقة موثوقة مع موقف مدرسي أصلي وتعليل.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"efd943c3-1ce1-4894-b379-b4fa17b98240","n":2,"title":"حقوق الطفل","passage":"تتصل حقوق الطفل بالحماية والتعليم والرعاية وعدم الاستغلال وفق مصادر حقوقية وقانونية معتبرة، مع احترام اختلاف الأطر القانونية. في مثال مستقل تتيح مكتبة ركنًا آمنًا يناسب أعمار القراء الصغار؛ يُستخدم لتفسير معنى الإتاحة.","question":"أي إجراء يدعم حق الطفل في التعلم في المثال؟","correct":"إتاحة بيئة قراءة آمنة ومناسبة","wrong":["منع جميع الكتب","تجاهل الأمان","إلغاء التعلم"],"practice":"قارن موقفًا مدرسيًا بعبارة صحيحة المصدر من وثيقة حقوق الطفل.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"efd943c3-1ce1-4894-b379-b4fa17b98240","n":3,"title":"حقوق المرأة","passage":"تُدرس حقوق المرأة بالرجوع إلى المصادر القانونية والاجتماعية الدقيقة مع تجنب تعميم حال امرأة واحدة على الجميع. في مثال مستقل تتيح مؤسسة التدريب للمتقدمين والمتقدمات معايير اختيار معلنة، ويُراجع القرار وفق الكفاءة والحقوق المعمول بها.","question":"ما الإجراء الذي يجعل الاختيار أكثر إنصافًا؟","correct":"معايير واضحة قابلة للمراجعة","wrong":["اختيار عشوائي سري","حكم مسبق على الأشخاص","حذف التقييم"],"practice":"اكتب فقرة تفرق بين مبدأ حقوقي ودليل اجتماعي وموقف تطبيقي.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"91aafacc-7aef-4e54-a601-fe95b4ac4c06","n":1,"title":"الأسرة","passage":"تتنوع أشكال الأسرة ومهام أفرادها وظروفهم، ومن المهم مراعاة الاحترام وتقاسم المسؤوليات والتواصل. في قصة أصلية تضع أسرة جدولًا يناسب وقت جميع أفرادها لتنظيم أعمال المنزل دون تحميل شخص كل المهام.","question":"ما الذي ساعد الأسرة في المثال على توزيع المسؤوليات؟","correct":"الاتفاق على جدول مناسب للجميع","wrong":["إخفاء الأعمال","منع النقاش","تجاهل الوقت"],"practice":"اكتب حوارًا محترمًا بين أفراد أسرة متخيلة حول تقسيم عمل منزلي.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"91aafacc-7aef-4e54-a601-fe95b4ac4c06","n":2,"title":"المخدرات","passage":"يمكن تحليل نص توعوي حول أضرار المخدرات بالتمييز بين الادعاءات الطبية والإرشادات الوقائية العامة والوصم الاجتماعي. تجنب وصف طرق استخدامها، واستند إلى جهات صحية معتمدة. في مثال مستقل يطلب طالب المساعدة من بالغ موثوق عند تلقي ضغط لإساءة استخدام مادة.","question":"ما الاستجابة الآمنة للضغط الذي يصفه المثال؟","correct":"رفض الضغط والرجوع إلى بالغ موثوق","wrong":["تجربة المادة","إخفاء الأمر عن كل داعم","تشجيع الآخرين"],"practice":"حلل رسالة توعوية من جهة صحية معتبرة وحدد الادعاء ومصدره والبدائل الداعمة.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"91aafacc-7aef-4e54-a601-fe95b4ac4c06","n":3,"title":"التدخين","passage":"يُناقش موضوع التدخين في نصوص توعوية بمعلومات صحية موثوقة حول مخاطره وبإبراز الوقاية وطلب الدعم عند الحاجة، دون وصم الأشخاص. نموذج مستقل يختار شاب بيئة خالية من التدخين ويناقش الأمر مع أسرته.","question":"ما الخيار الوقائي في المثال؟","correct":"اختيار بيئة خالية من التدخين","wrong":["تشجيع الاستخدام","إخفاء المصدر","تجاهل التهوية"],"practice":"اكتب فقرة توعوية تستند إلى مرجع صحي رسمي وتخلو من أحكام مسيئة.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"0b856348-b2bc-478b-94ba-f17994ae1772","n":1,"title":"مصادر الطاقة","passage":"تتنوع مصادر الطاقة بين متجددة وغير متجددة بحسب تجدد المورد وسياق الاستخدام، ويجب التمييز بين خصائص المصدر وكفاءته وتكلفته. في مثال مستقل تقارن مجموعة لوحين معلوماتيين عن الطاقة الشمسية والوقود وتتحقق من مصدر الأرقام.","question":"أي مصدر يُعد متجددًا في التصنيف العام؟","correct":"الطاقة الشمسية","wrong":["الفحم","النفط","الغاز الطبيعي"],"practice":"اكتب مقارنة مختصرة بين مصدرين مع ميزة وقيد ومصدر علمي.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"0b856348-b2bc-478b-94ba-f17994ae1772","n":2,"title":"وسائل الإنتاج","passage":"تشمل وسائل الإنتاج في التحليل الاقتصادي أدوات وتجهيزات وموارد تستخدم لإنتاج السلع أو الخدمات، وقد تختلف حسب القطاع. في مثال مستقل تستخدم ورشة نجارة أدوات آمنة ومواد خامًا وساعات عمل لإنتاج طاولة.","question":"ما وسيلة إنتاج مادية في المثال؟","correct":"أدوات الورشة","wrong":["عنوان الإعلان","اسم الشارع","رأي الزبون"],"practice":"حلل نشاطًا اقتصاديًا من اختيارك وحدد المدخلات والعمليات والمخرجات.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"0b856348-b2bc-478b-94ba-f17994ae1772","n":3,"title":"التجارة","passage":"تتصل التجارة بتبادل السلع والخدمات بين أطراف مع معلومات عن الجودة والسعر وشروط الاتفاق، وقد تختلف أشكالها من سوق محلي إلى منصة رقمية. في مثال مستقل تقارن طالبة عرضين لشراء كتاب بسعر وتكلفة شحن معلنين.","question":"ما الذي يلزم للمقارنة المنصفة بين عرضين؟","correct":"معرفة السعر الكامل وشروط الخدمة","wrong":["العنوان فقط","إخفاء تكلفة الشحن","الاعتماد على اللون"],"practice":"اكتب نصًا معلوماتيًا عن عملية بيع متخيلة يوضح الحقوق والأسعار دون ادعاء أرقام واقعية.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"aa1cdab5-2079-422b-92c6-0e683d04b68e","n":1,"title":"التلوث البيئي","passage":"يمكن أن يرتبط تلوث الهواء أو الماء أو التربة بمصادر مختلفة، ويتطلب إثبات تأثير معين بيانات علمية محددة بدل انطباع عام. في مثال مستقل يرصد فريق مخلفات بلاستيكية قرب مدرسة ويخطط لجمعها بطريقة آمنة.","question":"ما الإجراء المناسب قبل تعميم حكم عن مستوى التلوث؟","correct":"الحصول على بيانات قابلة للتحقق","wrong":["الاعتماد على صورة واحدة","اختلاق نسبة","تجاهل الموقع والوقت"],"practice":"اكتب تقرير ملاحظة بيئية مع مصدر وقيد واضحين.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"aa1cdab5-2079-422b-92c6-0e683d04b68e","n":2,"title":"مقاومة التصحر","passage":"تتصل مكافحة التصحر بإدارة التربة والمياه والغطاء النباتي على نحو يتناسب مع مناخ الموقع ومصادره، ولا توجد وصفة واحدة تصلح لكل منطقة. في نموذج أصلي يناقش فريق حماية شتلات مناسبة للبيئة وتقييم بقائها بعد موسم.","question":"ما الذي يساعد على اختيار إجراء مناسب لمقاومة التصحر؟","correct":"معرفة التربة والماء والمناخ المحلي","wrong":["زرع أي نبات بلا دراسة","إلغاء المتابعة","اختيار مكان عشوائي"],"practice":"ضع خطة توعوية بيئية بمدخلات محلية ومؤشر للمتابعة.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"aa1cdab5-2079-422b-92c6-0e683d04b68e","n":3,"title":"مشكلة المياه","passage":"تختلف مشكلات المياه بين قلة المورد وجودته وتوزيعه وإدارته، وتحتاج مناقشتها بيانات محلية وقياسًا لا افتراضًا عامًا. في مثال مستقل تصلح مدرسة صنبورًا يتسرب منه الماء وتراجع الاستهلاك قبل الإصلاح وبعده.","question":"ما الإجراء المباشر لتقليل الهدر في المثال؟","correct":"إصلاح التسرب ومراجعة الاستهلاك","wrong":["ترك الصنبور مفتوحًا","تجاهل القياس","إخفاء التسرب"],"practice":"اكتب فقرة تقترح حلًا لهدر المياه بوسيلة قياس قابلة للتحقق.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"495832cb-cefb-43b3-98f7-5d987dcceb71","n":1,"title":"عادات وتقاليد","passage":"تتنوع العادات والتقاليد باختلاف الأسر والأماكن والأجيال، ولذلك لا يصح تعميم ممارسة واحدة على جميع أفراد بلد. في مثال مستقل تعرض طالبة عادات ضيافة من منطقتها وتسأل زملاءها عن الاختلاف دون إصدار أحكام تفوق.","question":"ما المنهج المناسب لوصف عادة ثقافية؟","correct":"تحديد سياقها وتجنب التعميم","wrong":["الحديث باسم الجميع","السخرية من الاختلاف","اختلاق مصدر"],"practice":"اكتب وصفًا لعادة موثقة يتضمن مكانها وحدود انتشارها.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"495832cb-cefb-43b3-98f7-5d987dcceb71","n":2,"title":"المطالعة","passage":"تساعد المطالعة على بناء فهم أعمق عندما يختار القارئ نصًا مناسبًا ويدون الفكرة والشواهد والأسئلة، بدل عد الصفحات فقط. في مثال مستقل يسجل متعلم ملخصًا وتحفظًا على رأي الكاتب بعد قراءة مقالة.","question":"ما الذي يظهر قراءة نقدية في المثال؟","correct":"استخراج الفكرة ومناقشة شاهدها","wrong":["العد وحده","نسخ العنوان","إغلاق الكتاب مباشرة"],"practice":"اختر نصًا مأذونًا، واكتب بطاقة قراءة فيها فكرة وسؤال وشاهد.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"495832cb-cefb-43b3-98f7-5d987dcceb71","n":3,"title":"المسرح","passage":"يعتمد العرض المسرحي على حوار وشخصيات وصراع وحركة وإرشادات أداء، وقد تتغير دلالته بتغير المكان والإضاءة. في مثال أصلي يتجادل طالبان حول دورهما في تنظيم نشاط حتى يضعا قاعدة للاتفاق.","question":"ما العنصر الذي يطور المشهد المسرحي؟","correct":"حوار يقود إلى تحول في الموقف","wrong":["قائمة كلمات بلا حدث","وزن قصيدة","تعريف معجمي فقط"],"practice":"حوّل حكاية قصيرة إلى مشهد من شخصيتين مع إرشاد تمثيلي.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"647203af-bb4d-47cd-93f8-b08c5681e1fa","n":1,"title":"الرياضة والصحة","passage":"يمكن أن تدعم الحركة البدنية المنتظمة جوانب من الصحة بحسب العمر والقدرة والظروف، لكن النص التوعوي لا يقدم وصفة تدريب فردية أو نتيجة مضمونة. مثال مستقل يختار فريق أنشطة آمنة تناسب المشاركين مع فترات راحة.","question":"ما الممارسة المسؤولة في نشاط مدرسي بدني؟","correct":"مراعاة السلامة واختلاف القدرات","wrong":["إجبار الجميع على مستوى واحد","إلغاء الاستراحة","تجاهل الإشراف"],"practice":"اكتب نصًا إرشاديًا عامًا عن نشاط بدني مدرسي مع مصدر صحي مناسب.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"647203af-bb4d-47cd-93f8-b08c5681e1fa","n":2,"title":"الرياضة والعنف","passage":"تساعد القواعد والتحكيم والاحترام المتبادل على الحد من السلوك العدواني في المنافسات الرياضية. في مثال مستقل اختلف فريقان بشأن قرار حكم، ثم استخدما قناة اعتراض رسمية بدل التشاجر.","question":"ما التصرف الذي خفّض التوتر في المثال؟","correct":"الاعتراض المنظم باحترام","wrong":["الاعتداء على الحكم","إهانة الخصم","إلغاء القواعد"],"practice":"اكتب حوارًا بين فريقين يختلفان على قرار ويصلان إلى حل سلمي.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"647203af-bb4d-47cd-93f8-b08c5681e1fa","n":3,"title":"رياضات وشخصيات","passage":"تستلزم كتابة سيرة شخصية رياضية التحقق من الأرقام والبطولات والتواريخ من مصادر موثوقة؛ ولا يجوز اختلاق ميداليات أو نتائج. مثال مستقل يكتب طالب بطاقة تعريف لرياضية متخيلة ويضع بوضوح أنها شخصية افتراضية.","question":"ما المصدر الضروري لنقل إنجاز رياضي حقيقي؟","correct":"سجل موثق من جهة رياضية موثوقة","wrong":["خبر غير مؤرخ","حوار متخيل","صورة دون وصف"],"practice":"ابحث عن رياضي موثق وقدّم بطاقة تتضمن مصدرين وتحليل مهارة.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"262eabc5-1233-442e-a7b4-2be2c0742486","n":1,"title":"الوقاية","passage":"تُقرأ نصوص الوقاية الصحية بفحص الجهة الناشرة والتاريخ ونطاق النصائح، ولا تُستبدل التعليمات الرسمية بتوقعات شخصية. في مثال مستقل يغسل الطلاب أيديهم في موضع مناسب ضمن إجراءات النظافة العامة دون تقديم علاج خاص.","question":"ما الذي يعزز موثوقية نص وقائي؟","correct":"مصدر صحي معتمد ومعلومات حديثة","wrong":["رأي مجهول","إشاعة","تعميم تجربة فردية"],"practice":"راجع منشورًا صحيًا عامًا من مؤسسة موثوقة وحدد توصية واضحة ومصدرها.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"262eabc5-1233-442e-a7b4-2be2c0742486","n":2,"title":"الأمراض المعدية","passage":"قد تنتقل الأمراض المعدية بطرق مختلفة بحسب العامل المسبب، لذلك لا يصح افتراض طريق عدوى واحد لجميعها. يحتاج النص الصحي إلى مرجع طبي حديث ولغة غير موصمة؛ المثال المستقل طالب يسأل مختصًا عن إجراءات الوقاية المعتمدة.","question":"لماذا لا نعمم طريقة انتقال واحدة لكل الأمراض؟","correct":"لاختلاف العوامل المسببة وطرق الانتقال","wrong":["لأن الأمراض جميعها خيالية","لأن البيانات غير مهمة","لأن الأعراض متطابقة"],"practice":"اكتب فقرة تثقيفية غير علاجية تستند إلى مرجع صحي موثوق وتتجنب التعميم.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"262eabc5-1233-442e-a7b4-2be2c0742486","n":3,"title":"الأمراض المزمنة","passage":"تتفاوت الأمراض المزمنة في أسبابها ومساراتها والاحتياجات المتعلقة بها، ويجب احترام خصوصية الأشخاص وعدم تقديم تشخيص أو دواء من نص دراسي. في مثال مستقل تضع مدرسة ترتيبات مناسبة لطالب يحتاج راحة أثناء نشاط بعد التنسيق مع ذويه والجهات المختصة.","question":"ما السلوك التربوي المناسب في المثال؟","correct":"احترام الخصوصية وتوفير ترتيبات مناسبة","wrong":["نشر معلومات الطالب الصحية","تقديم علاج بلا مختص","منع كل مشاركة"],"practice":"حلل رسالة توعوية موثقة تتجنب الوصم وتدعم الوصول العادل للأنشطة.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"16cbc1d8-cf43-4bd6-a863-6af5a4215a85","n":1,"title":"العمل","passage":"يرتبط العمل بإنتاج منفعة وخدمة وتطوير مهارات ضمن حقوق ومسؤوليات تختلف حسب نوع العمل. في مثال مستقل ينظم فريق ورشة لنسخ الكتب القديمة قانونيًا وترتيبها بعد التأكد من حقوق الاستخدام.","question":"ما الذي يجعل أداء الفريق مسؤولًا؟","correct":"احترام الحقوق وتنظيم المهام","wrong":["إخفاء المصدر","نسخ مواد محمية بلا إذن","إلغاء المراجعة"],"practice":"اكتب فقرة عن مهارة مهنية وكيف يمكن تقويمها بمؤشر قابل للتحقق.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"16cbc1d8-cf43-4bd6-a863-6af5a4215a85","n":2,"title":"الحرف اليدوية","passage":"تجمع الحرف اليدوية بين معرفة المادة ومهارة التصميم والعمل الآمن والتدرج في الجودة، وتختلف ممارساتها بحسب البيئة. في مثال مستقل ينشئ متعلم قطعة ورقية بسيطة ويقارن ما خطط له بما أنجزه.","question":"ما الخطوة التي تسبق تحسين جودة المنتج اليدوي؟","correct":"مراجعة التصميم والنتيجة وفق معايير","wrong":["إخفاء الأخطاء","إلغاء السلامة","تغيير الهدف بلا سبب"],"practice":"صف حرفة محلية موثقة مع الأدوات الآمنة وخطوات عامة غير خطرة.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"16cbc1d8-cf43-4bd6-a863-6af5a4215a85","n":3,"title":"العلاقات المهنية","passage":"تقوم العلاقات المهنية الجيدة على وضوح التوقعات والتواصل والاحترام وحماية الخصوصية وتسوية الخلافات بطريقة منصفة. في نموذج أصلي يختلف زميلان على وقت تسليم مشروع فيراجعان الجدول ويتفقان على تعديل معلن.","question":"ما التصرف الذي حسّن التعاون بين الزميلين؟","correct":"مراجعة الجدول وتوثيق الاتفاق","wrong":["تبادل الإهانات","إخفاء المشكلة","تغيير موعد سري"],"practice":"اكتب رسالة مهنية مهذبة تطلب توضيح مسؤولية أو تعديل موعد.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"3c0d4252-7cbe-4b6e-90a2-611d85770919","n":1,"title":"المعارف (مراجعة)","passage":"تشمل المعارف أنواعًا مثل العلم والضمير واسم الإشارة والاسم الموصول والمعرف بأل والمضاف إلى معرفة وفق القاعدة. في «هذا كتابُ خالدٍ» «هذا» اسم إشارة معرفة و«خالد» علم، وتتأثر إضافة «كتاب» بتحديد المضاف إليه.","question":"أي كلمة اسم إشارة معرفة في المثال؟","correct":"هذا","wrong":["كتاب","خالد","من"],"practice":"صنف عشرة أسماء في جمل إلى معرفة ونكرة مع التعليل.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"3c0d4252-7cbe-4b6e-90a2-611d85770919","n":2,"title":"المبني والمعرب (مراجعة)","passage":"المعرب يتغير آخره بحسب موقعه مثل «الطالبُ، الطالبَ، الطالبِ»، بينما المبني يلزم آخره حالة واحدة في استعمالات كأسماء الإشارة. يتوقف الحكم على نوع الكلمة وموضعها لا على طولها.","question":"ما الذي يميز المعرب في الأمثلة المذكورة؟","correct":"تغير علامة آخره بحسب العامل","wrong":["ثبات آخره دائمًا","كونه فعلًا فقط","غياب الضبط"],"practice":"اكتب أمثلة لمعرب ومبني في ثلاث جمل مع إعراب صحيح.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"3c0d4252-7cbe-4b6e-90a2-611d85770919","n":3,"title":"الضمائر المتصلة والمنفصلة","passage":"في «أنا كتبتُ رسالتي» «أنا» ضمير منفصل و«التاء» في «كتبتُ» ضمير متصل مبني في محل رفع فاعل. تتنوع وظائف الضمائر المتصلة بحسب اتصالها بالفعل أو الاسم أو الحرف.","question":"ما نوع ضمير «أنا» في المثال؟","correct":"ضمير منفصل","wrong":["ضمير متصل","اسم موصول","حرف شرط"],"practice":"استخرج ستة ضمائر من فقرة وبيّن الاتصال والانفصال والمحل الإعرابي.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"3c0d4252-7cbe-4b6e-90a2-611d85770919","n":4,"title":"أدوات الاستفهام","passage":"تختلف أدوات الاستفهام في المطلوب: «أين» للمكان و«متى» للزمان و«كيف» للحال والطريقة و«كم» للعدد بحسب السياق. يحدد المتعلم الأداة من نوع السؤال لا من ترتيب الألفاظ وحده.","question":"بأي أداة نسأل عن المكان؟","correct":"أين","wrong":["متى","كيف","كم"],"practice":"كوّن خمسة أسئلة بأدوات مختلفة مع جواب يطابق المطلوب.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"3c0d4252-7cbe-4b6e-90a2-611d85770919","n":5,"title":"الأفعال المتعدية واللازمة وتعدية الفعل اللازم","passage":"في «قرأ الطالبُ الكتابَ» الفعل متعدٍّ إلى مفعول به، وفي «جلسَ الطالبُ» لا يأخذ الفعل مفعولًا به في استعماله المذكور. قد تختلف تعدية الفعل بحسب الصيغة أو الحرف أو السياق، فلا نعد كل اسم بعد الفعل مفعولًا.","question":"أي فعل متعد في المثال؟","correct":"قرأ","wrong":["جلس","نام","ذهب"],"practice":"اكتب أربعة أفعال لازمة وأخرى متعدية في جمل مع بيان أثر حرف الجر أو الهمزة عند التحويل إن صح.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"3c0d4252-7cbe-4b6e-90a2-611d85770919","n":6,"title":"أدوات النفي","passage":"تُستخدم «لم» لنفي المضارع وجزمه مع دلالة زمنية مناسبة مثل «لم يكتبْ»، و«لن» لنصب المضارع ونفي المستقبل بحسب السياق، و«لا» قد تستخدم للنفي أو النهي. لا تكفي تسمية الأداة دون أثرها الإعرابي.","question":"ما أثر «لم» في المضارع في المثال؟","correct":"تجزمه","wrong":["تنصبه دائمًا","تحوله اسمًا","تمنع وجود فاعل"],"practice":"حوّل ثلاث جمل مثبتة إلى منفية بأدوات مناسبة واضبط الفعل.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"3c0d4252-7cbe-4b6e-90a2-611d85770919","n":7,"title":"المبني للمعلوم والمبني للمجهول","passage":"في «كتبَ الطالبُ الدرسَ» الفعل مبني للمعلوم وفاعله ظاهر، وفي «كُتبَ الدرسُ» فعل مبني للمجهول و«الدرسُ» نائب فاعل مرفوع. يلزم ضبط الفعل والإسناد وعدم الخلط بين حذف الفاعل وحذف كل عناصر الجملة.","question":"ما إعراب «الدرسُ» في «كُتب الدرس»؟","correct":"نائب فاعل مرفوع","wrong":["مفعول به منصوب","اسم مجرور","حال"],"practice":"حوّل ثلاث جمل من معلوم إلى مجهول مع ضبط الفعل ونائب الفاعل.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"3c0d4252-7cbe-4b6e-90a2-611d85770919","n":8,"title":"أدوات الشرط الجازمة","passage":"في «إنْ تجتهدْ تنجحْ» «إن» أداة شرط جازمة، وتجزم فعل الشرط وجوابه في هذا التركيب. تختلف الأدوات الشرطية وأحكام اقتران الجواب بالفاء، فلا يُهمل السياق النحوي.","question":"ما أداة الشرط في «إن تجتهد تنجح»؟","correct":"إنْ","wrong":["لن","هل","سوف"],"practice":"اكتب أربع جمل شرطية صحيحة وميز الفعل والجواب والأداة.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"3c0d4252-7cbe-4b6e-90a2-611d85770919","n":9,"title":"المفعول لأجله","passage":"المفعول لأجله مصدر منصوب يبين سبب وقوع الفعل مع شروط معروفة، مثل «درستُ رغبةً في العلم»؛ «رغبةً» مصدر يدل على علة الدراسة. قد يُعبَّر عن السبب باللام أو غيرها في تراكيب أخرى.","question":"ما وظيفة «رغبةً» في المثال؟","correct":"مفعول لأجله منصوب","wrong":["فاعل","مضاف إليه","خبر إن"],"practice":"كوّن ثلاثة أمثلة للمفعول لأجله ثم قارنها بتراكيب تعليل باللام.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"3c0d4252-7cbe-4b6e-90a2-611d85770919","n":10,"title":"المجرد والمزيد","passage":"الفعل المجرد حروفه أصلية في بنيته، مثل «كتب»، وقد تُزاد أحرف لإفادة معنى أو بناء صيغة مثل «كاتب» على بناء «فاعل» بوصفه فعلًا ماضيًا في سياق مناسب. نميز حروف الزيادة من حروف الجذر ونراجع أثر الصيغة في المعنى.","question":"ما الجذر الثلاثي الذي يعود إليه «كاتب» الفعل؟","correct":"كتب","wrong":["كتبب","كتتب","تاب"],"practice":"حلل ستة أفعال مجردة ومزيدة، واذكر الجذر وحروف الزيادة وتغير المعنى.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"e2f270b8-cb9f-4505-9acb-661158b40338","n":1,"title":"الصحف والمجلات","passage":"تختلف الصحف والمجلات في دورية النشر والجمهور وأنواع المادة والتحرير، ويحتاج القارئ إلى تمييز الخبر من المقال والإعلان. في مثال مستقل يقرأ طالب مقالًا ويبحث عن اسم الكاتب وتاريخ المادة والمراجع قبل الاستشهاد.","question":"ما الذي يساعد على التحقق من مادة صحفية؟","correct":"اسم الناشر والتاريخ والمصدر","wrong":["عدد الصور فقط","حجم العنوان","شعبية المحتوى"],"practice":"قارن خبرًا ومقال رأي من مصدرين معلومين مع فصل الوقائع عن التفسير.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"e2f270b8-cb9f-4505-9acb-661158b40338","n":2,"title":"الإعلام المرئي والسمعي","passage":"يعتمد الإعلام المرئي والسمعي على الصورة أو الصوت وأسلوب العرض، وقد تؤثر الموسيقى وطريقة المونتاج في تفسير القارئ للواقعة. ينبغي التحقق من التاريخ ومصدر المقطع وعدم اعتباره دليلًا مكتملًا من دون سياق.","question":"ما الذي يجب فحصه عند تداول مقطع إعلامي؟","correct":"المصدر والتاريخ وسياق التحرير","wrong":["عدد المشاهدات وحده","الإيقاع فقط","لون الشعار"],"practice":"صمم سيناريو تعليميًا قصيرًا يصحبه وصف مصدر كل معلومة.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"e2f270b8-cb9f-4505-9acb-661158b40338","n":3,"title":"الإنترنت","passage":"تتيح الشبكة الوصول إلى معلومات كثيرة متفاوتة الجودة، لذلك يحتاج الباحث فحص الجهة الناشرة والتاريخ وروابط الأدلة والخصوصية، ولا يحكم على الصحة من ظهور النتيجة أولًا. نموذج مستقل يقارن طالب نتيجتي بحث قبل كتابة خلاصة.","question":"ما خطوة التحقق المناسبة قبل إعادة نشر معلومة؟","correct":"مراجعة مصدرها وأدلتها","wrong":["الاعتماد على أول نتيجة","نسخها دون قراءة","إخفاء الرابط"],"practice":"ضع قائمة من أربعة معايير لتقييم صفحة تعليمية منشورة.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"cae21fd1-1bc7-4987-8fab-7adec14cb61a","n":1,"title":"التعلق بالوطن","passage":"يمكن أن يظهر الانتماء للوطن في الحفاظ على المرافق وخدمة المجتمع واحترام الناس، دون حصره في شعار أو افتراض أن الجميع يعيش التجربة نفسها. مثال مستقل ينظم طلاب حملة لإصلاح ركن قراءة عام بالتعاون مع الجهة المسؤولة.","question":"ما الفعل الذي يجسد الانتماء في المثال؟","correct":"خدمة مرفق مشترك باحترام القواعد","wrong":["الإضرار بالمرفق","منع الآخرين","إخفاء الأدوات"],"practice":"اكتب فقرة عن مساهمة مجتمعية مسؤولة مع سبب ومثال غير منسوب لتاريخ.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"cae21fd1-1bc7-4987-8fab-7adec14cb61a","n":2,"title":"المسؤولية","passage":"تعني المسؤولية وضوح الالتزام والقدرة على شرح القرار وتحمّل أثره وتصحيح الخطأ. في مثال مستقل يعترف عضو فريق بأنه نسي إرسال الملف، ويقترح موعدًا جديدًا ومراجعة تمنع تكرار المشكلة.","question":"ما السلوك الذي أظهر تحمّل المسؤولية؟","correct":"الإقرار بالخطأ وخطة تصحيحه","wrong":["اتهام الآخرين بلا دليل","إخفاء المشكلة","إلغاء التسليم"],"practice":"اكتب موقفًا واقعيًا أو متخيلًا يتضمن خطأً وإصلاحًا ومعيارًا للتحسن.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"},{"cid":"b5284bbc-0469-4d59-9694-0a44af3e67f3","unit":"cae21fd1-1bc7-4987-8fab-7adec14cb61a","n":3,"title":"التسامح","passage":"يشمل التسامح احترام اختلاف الآراء والأشخاص وتجنب الإيذاء، دون التنازل عن الحقوق الأساسية. في مثال مستقل يختلف طالبان حول موضوع قراءة ويتفقان على الاستماع للحجج ثم اختيار نص مشترك.","question":"أي سلوك يعكس التسامح؟","correct":"الاستماع والاحترام رغم الاختلاف","wrong":["السخرية من الرأي الآخر","إسكات الزميل","فرض القرار دون نقاش"],"practice":"اكتب حوارًا قصيرًا يبين احترام رأيين مع قاعدة لحل الخلاف.","old":"DADYOOM_DJ_G10_OFFICIAL_PROGRAMME"}]'::jsonb)
 AS x(cid uuid,unit uuid,n integer,title text,passage text,question text,correct text,wrong text[],practice text,old text)
 LOOP
  SELECT l.id,l.content INTO STRICT target_id,prior
  FROM public.lessons l JOIN public.units u ON u.id=l.unit_id
  JOIN public.grades g ON g.id=u.grade_id
  JOIN public.curricula c ON c.id=g.curriculum_id
  JOIN public.countries co ON co.id=c.country_id
  WHERE co.code='DJ' AND c.id=r.cid
    AND g.grade_number=10 AND u.semester IS NULL AND u.id=r.unit
    AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
  FOR UPDATE OF l;

  SELECT count(*) INTO hasprogress FROM public.student_lesson_progress WHERE lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'DJ_G10_HAS_PROGRESS_%',r.title; END IF;
  SELECT count(*) INTO hasprogress FROM public.lesson_activity_attempts att
    JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
  IF hasprogress<>0 THEN RAISE EXCEPTION 'DJ_G10_HAS_ATTEMPTS_%',r.title; END IF;
  IF char_length(coalesce(prior,''))>=350 THEN RAISE EXCEPTION 'DJ_G10_ALREADY_CONTENT_%',r.title; END IF;
  SELECT count(*) INTO nact FROM public.lesson_activities
    WHERE lesson_id=target_id AND content->>'origin'=r.old AND answer='{}'::jsonb;
  IF nact<>3 THEN RAISE EXCEPTION 'DJ_G10_EXPECTED_3_PLACEHOLDERS_%',r.title; END IF;

  UPDATE public.lessons SET
    content='ضاديوم — إثراء تعليمي أصلي للسنة الرابعة الإعدادية في موريتانيا. هذا ليس نص الكتاب المعتمد ولا تأكيدًا لمطابقة جميع الفصول؛ الاسم مستورد ويلزم تحقق وزاري.'
    ||E'\n\n'||'عنوان الدرس: '||r.title
    ||E'\n\n'||'هدف التعلم: أن يشرح المتعلم فكرة أو قاعدة من المجال، ويحلل قرينة أو شاهدًا صحيح النسبة، ويكتب استجابة جديدة تستند إلى دليل.'
    ||E'\n\n'||'شرح وتطبيق أصلي: '||r.passage
    ||E'\n\n'||'سؤال فهم: '||r.question
    ||E'\n\n'||'تطبيق كتابي مستقل: '||r.practice
    ||E'\n\n'||'التمايز: دعم بقائمة مفردات وخطوات تحليل أساسية، ومستوى متوسط يبرر الاختيار، ومستوى متقدم يقارن بين تفسيرين أو يختبر دقة المصدر. يتولى المعلم مراجعة مهام الكتابة.'
    ||E'\n\n'||'تحذير المصدر: لا تُنسب أمثلة ضاديوم إلى شاعر أو مؤرخ أو نص ديني؛ راجع المصدر المعتمد أولًا.'
    ||E'\n\n'||'المحتوى السابق المحفوظ: '||coalesce(prior,''),
    updated_at=now() WHERE id=target_id;

  UPDATE public.lesson_activities SET
    prompt='اقرأ النص التدريبي المستقل، واستخرج منه الفكرة أو الشاهد الذي تستند إليه الإجابة.',
    content=content||jsonb_build_object('origin','DADYOOM_DJ_G10_ORIGINAL_46_20261009','previousOrigin',r.old,
      'text',r.passage,'notOfficialBook',true,'sourceVerification','pending')
    WHERE lesson_id=target_id AND activity_type='reading'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.question,
    content=content||jsonb_build_object('origin','DADYOOM_DJ_G10_ORIGINAL_46_20261009','previousOrigin',r.old,
       'text',r.question,'notOfficialBook',true,'sourceVerification','pending',
       'options',CASE (r.n%4)
       WHEN 0 THEN jsonb_build_array(r.correct,r.wrong[1],r.wrong[2],r.wrong[3])
       WHEN 1 THEN jsonb_build_array(r.wrong[1],r.correct,r.wrong[2],r.wrong[3])
       WHEN 2 THEN jsonb_build_array(r.wrong[1],r.wrong[2],r.correct,r.wrong[3])
       ELSE jsonb_build_array(r.wrong[1],r.wrong[2],r.wrong[3],r.correct) END),
    answer=jsonb_build_object('correct',r.correct)
    WHERE lesson_id=target_id AND activity_type='multiple_choice'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  UPDATE public.lesson_activities SET prompt=r.practice,
    content=content||jsonb_build_object('origin','DADYOOM_DJ_G10_ORIGINAL_46_20261009','previousOrigin',r.old,
     'text',r.practice,'notOfficialBook',true,'sourceVerification','pending',
     'humanReviewRequired',true)
    WHERE lesson_id=target_id AND activity_type='writing'
      AND content->>'origin'=r.old AND answer='{}'::jsonb;

  SELECT count(*) INTO nact FROM public.lesson_activities
   WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_DJ_G10_ORIGINAL_46_20261009';
  IF nact<>3 THEN RAISE EXCEPTION 'DJ_G10_ACTIVITY_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;